import re
from pathlib import Path
text=re.sub(r'\x1b\[[0-?]*[ -/]*[@-~]','',Path('results/run100/train.log').read_text())
lines=[re.sub(r'^\([^)]*\) ','',l) for l in text.splitlines()]
for start,end in [(335,453),(625,674),(840,867),(885,968),(1090,1160),(1580,1625)]:
 print('\nLINES',start,end)
 for i,l in enumerate(lines[start-1:end],start):
  print(f'{i}: {l[:1000]}')
PY"],
 ["data_integrity","python3 -B - <<'PY'
import pyarrow.parquet as pq, re,hashlib
from pathlib import Path
processed={}
for split in ('train','test'):
 raw=pq.read_table(f'data/raw/gsm8k/main/{split}-00000-of-00001.parquet').to_pylist()
 data=pq.read_table(f'data/gsm8k/{split}.parquet').to_pylist()
 processed[split]=data
 print(split,'raw',len(raw),'processed',len(data),'schema',pq.read_schema(f'data/gsm8k/{split}.parquet'))
 bad=[]
 for i,(r,d) in enumerate(zip(raw,data)):
  gold=re.search(r'#### (\-?[0-9\.,]+)',r['answer']).group(1).replace(',','')
  expected=r['question']+' Let\'s think step by step and output the final answer after "####".'
  if d['prompt']!=[{'role':'user','content':expected}] or d['reward_model']!={'style':'rule','ground_truth':gold} or d['extra_info']!={'split':split,'index':i,'answer':r['answer'],'question':r['question']} or d['data_source']!='openai/gsm8k':
   bad.append(i)
 print('mapping mismatch count',len(bad),'sample',data[0])
print('exact question train/test overlap',len({d['extra_info']['question'] for d in processed['train']} & {d['extra_info']['question'] for d in processed['test']}))
for p in ['run_gsm8k_grpo.sh','rewards/gsm8k_reward.py','data/gsm8k/train.parquet','data/gsm8k/test.parquet']:
 print('sha256',p,hashlib.sha256(Path(p).read_bytes()).hexdigest())
